/* Actual P20 review controls: no offline artwork boards used as game sprites. */
(function(){'use strict';
 const el=document.createElement('div');el.id='p20-base-review';el.hidden=true;
 el.innerHTML='<div role="dialog" aria-modal="true" aria-label="P20 base review"><h2>Retained Base 0.4 review tools</h2><p>Bag-first Inventory, smaller item artwork and captioned main controls. Jimmy v0.6 artwork is a partial checkpoint under review; the painted Watch House remains default.</p><div class="review-actions"></div><p class="review-status" role="status"></p><button class="review-close">Return to game</button></div>';
 const style=document.createElement('style');style.textContent='#p20-base-review{position:fixed;inset:0;z-index:20000;background:#071319ee;padding:12px;display:flex;align-items:center;justify-content:center;font:16px/1.45 system-ui;color:#23383b}#p20-base-review[hidden]{display:none}#p20-base-review>div{background:#f7f1e1;border:1px solid #a7804e;border-radius:12px;padding:16px;width:min(520px,100%);max-height:95dvh;overflow:auto}#p20-base-review h2{margin:0;font:24px Georgia}#p20-base-review button{display:block;width:100%;min-height:48px;padding:10px;margin-top:8px;background:#203a43;color:#fff4df;border:1px solid #a7804e;border-radius:8px;font:600 16px system-ui}#p20-base-review .review-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}#p20-base-review .review-status{font-size:14px}@media(max-width:330px){#p20-base-review .review-actions{grid-template-columns:1fr}}';document.head.appendChild(style);document.body.appendChild(el);
 let last=null,wasInert=false;
 const close=()=>{if(el.hidden)return;el.hidden=true;window.CW_P20_INPUT_BLOCKED=false;const app=document.getElementById('app');if(app)app.inert=wasInert;window.dispatchEvent(new CustomEvent('cw:p20-modal',{detail:{open:false}}));const target=last?.isConnected&&last.getClientRects().length?last:document.getElementById('p13-menu-launch');target?.focus?.();};
 const status=el.querySelector('.review-status');const api=()=>window.CW_P20_BASE;
 function show(){if(!el.hidden)return;last=document.activeElement;const app=document.getElementById('app');wasInert=!!app?.inert;if(app)app.inert=true;window.CW_P20_INPUT_BLOCKED=true;document.querySelectorAll('#app .dpad button').forEach(b=>b.dispatchEvent(new Event('pointercancel')));window.dispatchEvent(new CustomEvent('cw:p20-modal',{detail:{open:true}}));el.hidden=false;status.textContent='Frontage: '+(api()?.report().frontageEnabled?'nonfinal candidate':'original painted source')+'. Existing lamp, bench and planter placements retained. No map or collision changes.';el.querySelector('button')?.focus();}
 const actions=[['Open sack Inventory',()=>window.CW_P16_EQUIPMENT?.open()],['Watch view · fit',()=>api()?.focus('watch')],['Whole square · fit',()=>api()?.focus('wide')],['Follow recruit',()=>api()?.follow()],['Show frontage candidate',()=>{api()?.setFrontage(true);api()?.focus('watch');}],['Show original frontage',()=>{api()?.setFrontage(false);api()?.focus('watch');}],['Sack appearance',()=>{window.CW_P16_EQUIPMENT?.setPresentation('sack');window.CW_P16_EQUIPMENT?.open();}],['Text / glyph fallback review',()=>{window.CW_P16_EQUIPMENT?.setPresentation('source');window.CW_P16_EQUIPMENT?.open();}]];
 for(const [label,fn]of actions){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{close();fn();};el.querySelector('.review-actions').appendChild(b);}
 el.querySelector('.review-close').onclick=close;el.addEventListener('click',e=>{if(e.target===el)close();});
 el.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Escape'){e.preventDefault();close();}else if(e.key==='Tab'){const bs=[...el.querySelectorAll('button')],first=bs[0],last=bs.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
 window.CW_P20_REVIEW={open:show};
})();
